package dev.baranhan.viltrumitecore.client.sinclair;

import dev.baranhan.viltrumitecore.client.anim.AnimCache;
import dev.baranhan.viltrumitecore.client.anim.animation.Animation;
import java.util.List;
import javax.annotation.Nullable;
import net.minecraft.resources.ResourceLocation;

/**
 * Sinclair art paths (all generated by tools/assets/make_sinclair_model.py, make_sinclair_clips.py
 * and make_sinclair_icons.py). Clips are split over several files; {@link #clip} looks a name up in all.
 */
public final class SinclairAssets {
   public static final ResourceLocation BODY = loc("geo/sinclair/sinclair.geo.json");
   public static final ResourceLocation ARMS = loc("geo/sinclair/sinclair_arms.geo.json");
   public static final ResourceLocation SAVANNAH = loc("geo/sinclair/savannah.geo.json");
   public static final ResourceLocation RABBIT = loc("geo/sinclair/rabbit.geo.json");
   public static final ResourceLocation TOP_HAT = loc("geo/sinclair/top_hat.geo.json");
   public static final ResourceLocation CHEST = loc("geo/sinclair/chest.geo.json");
   public static final ResourceLocation SWORD = loc("geo/sinclair/sword.geo.json");
   public static final ResourceLocation CARD = loc("geo/sinclair/card.geo.json");
   public static final ResourceLocation CURTAIN = loc("geo/sinclair/curtain.geo.json");

   public static final ResourceLocation TEXTURE = loc("textures/entity/sinclair/sinclair.png");
   public static final ResourceLocation GLOW = loc("textures/entity/sinclair/sinclair_glow.png");
   public static final ResourceLocation SAVANNAH_TEXTURE = loc("textures/entity/sinclair/savannah.png");
   public static final ResourceLocation SAVANNAH_GLOW = loc("textures/entity/sinclair/savannah_glow.png");
   public static final ResourceLocation RABBIT_TEXTURE = loc("textures/entity/sinclair/rabbit.png");
   public static final ResourceLocation RABBIT_GLOW = loc("textures/entity/sinclair/rabbit_glow.png");
   public static final ResourceLocation PROPS_TEXTURE = loc("textures/entity/sinclair/props.png");
   public static final ResourceLocation PROPS_GLOW = loc("textures/entity/sinclair/props_glow.png");

   public static final ResourceLocation HERO_ICON = loc("textures/gui/sinclair/hero.png");
   public static final ResourceLocation EMBLEM = loc("textures/gui/sinclair/emblem.png");
   public static final ResourceLocation ACT_CARD_ICON = loc("textures/gui/sinclair/act_card.png");

   private static final List<ResourceLocation> CLIP_FILES = List.of(
      loc("animations/sinclair/sinclair_base.animation.json"),
      loc("animations/sinclair/sinclair_moves.animation.json"),
      loc("animations/sinclair/sinclair_acts_a.animation.json"),
      loc("animations/sinclair/sinclair_acts_b.animation.json"),
      loc("animations/sinclair/sinclair_fp.animation.json"),
      loc("animations/sinclair/sinclair_fp_acts.animation.json"),
      loc("animations/sinclair/savannah.animation.json"),
      loc("animations/sinclair/rabbit.animation.json"),
      loc("animations/sinclair/props.animation.json"));

   /** Model px from the ground to the eyes (first-person anchor; vanilla eye height / PLAYER_SCALE). */
   public static final float EYE_PX = 27.6F;
   /** Vanilla PlayerRenderer.scale: the 32 px tall body stands like a player. */
   public static final float PLAYER_SCALE = 0.9375F;

   private SinclairAssets() {
   }

   /** A generated clip by name from any Sinclair animation file, or null while resources load. */
   @Nullable
   public static Animation clip(String name) {
      for (ResourceLocation file : CLIP_FILES) {
         Animation clip = AnimCache.animation(file, name);
         if (clip != null) {
            return clip;
         }
      }

      return null;
   }

   private static ResourceLocation loc(String path) {
      return new ResourceLocation("viltrumitecore", path);
   }
}
